/* @lc app=leetcode id=3791 lang=kotlin */ class Solution { fun go(ds: List<Int>?, L: Int, pos: Int, diff: Int, tight: Boolean, memo: HashMap<Int, Long>): Long = if (pos == L) (if (diff == 0) 1L else 0L) else memo.getOrPut((pos * 400 + diff + 200) * 2 + (if (tight) 1 else 0)) { ((if (pos == 0) 1 else 0)..(if (tight) ds!![pos] else 9)).sumOf { d -> go(ds, L, pos + 1, diff + (if (pos % 2 == 0) d else -d), tight && ds != null && d == ds[pos], memo) } } fun f(n: Long): Long = n.toString().map { it - '0' }.let { ds -> if (ds.size < 2) 0L else (2 until ds.size).sumOf { L -> go(null, L, 0, 0, false, HashMap()) } + go(ds, ds.size, 0, 0, true, HashMap()) } fun countBalanced(low: Long, high: Long): Long = f(high) - f(low - 1) }